<?php
require_once __DIR__.'/lib/data.php';require_once __DIR__.'/lib/ui.php';
$t=dataset_bundle('titulados');$e=dataset_bundle('empleadores');page_start('Reportes','reportes.php','Resultados principales y archivos para exportar');if(!$t&&!$e){empty_state('Importa datos para generar reportes.');page_end();exit;}
function first_key(array $a): string{return $a?array_key_first($a):'Sin datos';}
$summary=[];$heat=null;$radar=[];$findings=[];
if($t){$r=$t['rows'];$m=$t['map'];$n=count($r);$vida=numeric_values(values_for($r,$m['vida_profesional']??null));$sit=frequencies(values_for($r,$m['situacion_laboral']??null));$inter=frequencies(values_for($r,$m['interes_posgrado']??null));$area=frequencies(values_for($r,$m['area_interes']??null));$nivel=frequencies(values_for($r,$m['nivel_posgrado']??null));$fin=frequencies(values_for($r,$m['financiamiento']??null));$act=count_match($sit,['trabajando un una organizacion','trabajando en una organizacion'])+count_match($sit,['emprendimiento propio']);$siInt=count_match($inter,['si']);
$summary[]=['Titulados','Respuestas',$n];$summary[]=['Titulados','Actividad laboral',pct($act,$n)];$summary[]=['Titulados','Promedio de vida profesional',mean($vida)!==null?number_format(mean($vida),2).' años':'N/D'];$summary[]=['Titulados','Mediana',median($vida)!==null?number_format(median($vida),2).' años':'N/D'];$summary[]=['Titulados','Desviación estándar',stddev($vida)!==null?number_format(stddev($vida),2).' años':'N/D'];$summary[]=['Titulados','Interés en posgrado',pct($siInt,array_sum($inter))];
if($area)$findings[]='El área académica con mayor interés es '.first_key($area).' ('.reset($area).' respuestas).';if($nivel)$findings[]='El nivel de formación complementaria más frecuente es '.first_key($nivel).' ('.reset($nivel).' respuestas).';if($fin)$findings[]='La fuente de financiamiento más frecuente es '.first_key($fin).' ('.reset($fin).' respuestas).';
if(!empty($m['nivel_posgrado'])&&!empty($m['financiamiento']))$heat=contingency($r,$m['nivel_posgrado'],$m['financiamiento']);
}
if($e){$r=$e['rows'];$m=$e['map'];$n=count($r);$cont=frequencies(values_for($r,$m['contrato_5']??null));$fut=frequencies(values_for($r,$m['contratacion_futura']??null));$form=frequencies(values_for($r,$m['formacion_demandada']??null));$si=count_match($cont,['si']);$pos=count_match($fut,['alta probabilidad'])+count_match($fut,['dependiendo del crecimiento']);$summary[]=['Empleadores','Organizaciones',$n];$summary[]=['Empleadores','Contrató Ing. de Sistemas',pct($si,array_sum($cont))];$summary[]=['Empleadores','Posibilidad de contratación futura',pct($pos,array_sum($fut))];if($form)$findings[]='La formación más solicitada por los empleadores es '.first_key($form).' ('.reset($form).' respuestas).';
$defs=[['brinda confianza a nuestra organizacion','Confianza'],['titulo profesional otorgado','Título y competencias'],['perfil profesional declarado por la carrera de ingenieria de sistemas es coherente','Perfil'],['desempeno profesional de los titulados de ingenieria de sistemas evidencia','Competencias'],['demuestran valores y actitudes relacionados con la etica profesional','Ética']];foreach($defs as[$needle,$label]){$h=find_header($e['headers'],[$needle]);$s=likert_stats_1to5($e['rows'],$h);if($s)$radar[$label]=$s['mean'];}
}
