<h2 class="section-title numbered"><span>3</span>Cruce de formación y financiamiento</h2>
<?php if($heat):[$ac,$bc,$mx,$nn]=$heat;$mxv=0;foreach($mx as $row)foreach($row as $v)$mxv=max($mxv,$v);?><div class="card"><div class="cross-title"><div><h3 class="panel-title">Nivel de formación complementaria × fuente de financiamiento</h3></div><a class="text-link" href="cruces.php">Abrir análisis estadístico</a></div><div class="table-wrap"><table class="heat"><thead><tr><th>Nivel</th><?php foreach($bc as $b):?><th><?=h($b)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($ac as $a):?><tr><th><?=h($a)?></th><?php foreach($bc as $b):$v=$mx[$a][$b];$cl=$mxv?min(4,max(1,(int)ceil($v/$mxv*4))):1;?><td class="h<?=$cl?>"><?=$v?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></div><?php else:?><div class="card"><p class="muted">No hay datos suficientes para construir la matriz.</p></div><?php endif;?>

<h2 class="section-title numbered"><span>4</span>Valoración de los empleadores</h2>
<?php if($radar):$vals=array_values($radar);$labels=array_keys($radar);$cx=190;$cy=170;$R=110;$pts=[];$axes='';$count=count($vals);for($i=0;$i<$count;$i++){$ang=-M_PI/2+2*M_PI*$i/$count;$x=$cx+$R*cos($ang);$y=$cy+$R*sin($ang);$axes.='<line x1="'.$cx.'" y1="'.$cy.'" x2="'.$x.'" y2="'.$y.'" stroke="#cbd5e1"/><text x="'.($cx+($R+34)*cos($ang)).'" y="'.($cy+($R+34)*sin($ang)).'" font-size="10" text-anchor="middle">'.h($labels[$i]).'</text>';$rr=$R*($vals[$i]/5);$pts[]=($cx+$rr*cos($ang)).','.($cy+$rr*sin($ang));}?><div class="card radar-card"><svg viewBox="0 0 380 340"><circle cx="190" cy="170" r="110" fill="none" stroke="#e2e8f0"/><circle cx="190" cy="170" r="82.5" fill="none" stroke="#e2e8f0"/><circle cx="190" cy="170" r="55" fill="none" stroke="#e2e8f0"/><?=$axes?><polygon points="<?=implode(' ',$pts)?>" fill="rgba(37,99,235,.18)" stroke="#2563eb" stroke-width="2"/></svg><div class="radar-values"><?php foreach($radar as $label=>$v):?><div><span><?=h($label)?></span><b><?=number_format($v,2)?> / 5</b></div><?php endforeach;?></div></div><?php else:?><div class="card"><p class="muted">No hay valoraciones suficientes.</p></div><?php endif;?>

